import React, { useState } from "react";
import api from "@landinghub/api";
import Background from "../components/Background";
import { CheckCircle2 } from "lucide-react";
import "../styles/Contact.css";

const Contact = () => {
  const [form, setForm] = useState({ name: "", email: "", phone: "", notes: "" });
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email) {
      alert("Tên và Email là bắt buộc!");
      return;
    }
    try {
      await api.post("/api/leads", { ...form, status: "new" });
      setSubmitted(true);
      setForm({ name: "", email: "", phone: "", notes: "" });
      setTimeout(() => setSubmitted(false), 4000);
    } catch (err) {
      console.error(err);
      alert("Gửi thông tin thất bại. Vui lòng thử lại.");
    }
  };

  return (
    <Background showShapes={false} fullWidth={true}>
      <div className="contact-page">

        {/* Hero */}
        <section className="contact-hero">
          <h1>Liên hệ với chúng tôi</h1>
          <p>Hãy gửi thông tin của bạn, chúng tôi sẽ phản hồi sớm nhất!</p>
        </section>

        {/* Form */}
        <section className="contact-form-section">
          <div className="contact-card">
            {submitted && (
              <div className="success-message">
                <CheckCircle2 size={24} /> Cảm ơn! Chúng tôi đã nhận thông tin của bạn.
              </div>
            )}
            <form className="contact-form" onSubmit={handleSubmit}>
              <input name="name" value={form.name} onChange={handleChange} placeholder="Họ tên" required />
              <input name="email" type="email" value={form.email} onChange={handleChange} placeholder="Email" required />
              <input name="phone" value={form.phone} onChange={handleChange} placeholder="Số điện thoại" />
              <textarea name="notes" value={form.notes} onChange={handleChange} placeholder="Nội dung" />
              <button type="submit" className="btn-submit">Gửi thông tin</button>
            </form>
          </div>
        </section>

        {/* CTA */}
        <section className="contact-cta">
          <h2>Chúng tôi luôn sẵn sàng hỗ trợ bạn</h2>
          <p>Đừng ngần ngại gửi yêu cầu, đội ngũ của chúng tôi sẽ phản hồi nhanh chóng.</p>
        </section>

      </div>
    </Background>
  );
};

export default Contact;
